@props([
    'name' => null,
    'title' => null,
    'description' => null,
    'shortcut' => null,
    'closable' => false,
    'dismissible' => true,
    'open' => false,
])

@php
    $resolvedTitle = filled($title)
        ? (string) $title
        : __('stencil-ui::messages.command_palette_title');
    $resolvedDescription = filled($description)
        ? (string) $description
        : __('stencil-ui::messages.command_palette_description');

    $dialogId = 'command-dialog-'.str_replace('.', '', uniqid('', true));
    $titleId = $dialogId.'-title';
    $descriptionId = $dialogId.'-description';

    $normalizedShortcut = filled($shortcut)
        ? strtolower(str_replace([' ', '+'], ['', '.'], (string) $shortcut))
        : null;

    if ($normalizedShortcut !== null) {
        $normalizedShortcut = str_replace(['cmd.', 'command.'], 'meta.', $normalizedShortcut);
    }

    $dialogClasses = collect([
        'command__dialog',
        'dialog__content',
        'fixed left-1/2 top-[12vh] z-50 w-[calc(100%-2rem)] max-w-lg -translate-x-1/2 overflow-hidden rounded-xl border border-zinc-200 bg-white p-0 text-zinc-950 shadow-xl',
        'dark:border-zinc-800 dark:bg-zinc-950 dark:text-zinc-50',
        'backdrop:bg-zinc-950/50 backdrop:backdrop-blur-[2px]',
        'motion-safe:transition-[opacity,transform] motion-safe:duration-200 motion-safe:ease-[cubic-bezier(0.16,1,0.3,1)]',
        'open:opacity-100 open:motion-safe:scale-100',
        'opacity-0 motion-safe:scale-[0.98]',
    ])->implode(' ');

    $closeButtonClasses = 'absolute right-3 top-2.5 z-10 inline-flex size-8 items-center justify-center rounded-md text-zinc-500 transition hover:bg-zinc-100 hover:text-zinc-900 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-zinc-950/10 dark:text-zinc-400 dark:hover:bg-zinc-800 dark:hover:text-zinc-50 dark:focus-visible:ring-zinc-300/20';
@endphp

<dialog {{
    $attributes->class($dialogClasses)->merge([
        'data-dialog-content' => true,
        'data-command-dialog' => true,
        'data-dialog-dismissible' => $dismissible ? 'true' : 'false',
        'data-dialog-name' => filled($name) ? $name : null,
        'data-command-shortcut' => $normalizedShortcut,
        'aria-modal' => 'true',
        'aria-labelledby' => $titleId,
        'aria-describedby' => $descriptionId,
        'role' => 'dialog',
        'open' => $open ? true : null,
    ])
}}>
    <div
        class="dialog__panel relative flex max-h-[min(76vh,calc(100dvh-4rem))] flex-col overflow-hidden p-0"
        data-dialog-panel
    >
        <h2 id="{{ $titleId }}" class="sr-only" data-dialog-title="{{ $titleId }}">{{ $resolvedTitle }}</h2>
        <p id="{{ $descriptionId }}" class="sr-only" data-dialog-description="{{ $descriptionId }}">
            {{ $resolvedDescription }}
        </p>

        @if ($closable)
            <button
                type="button"
                class="{{ $closeButtonClasses }}"
                data-dialog-close
                aria-label="{{ __('stencil-ui::messages.dialog_close') }}"
            >
                <x-ui::icon name="x" class="size-4" />
            </button>
        @endif

        {{ $slot }}
    </div>
</dialog>

@php
    $emptyClasses = collect([
        'command__empty',
        'py-6 text-center text-sm text-zinc-500 dark:text-zinc-400',
    ])->implode(' ');
@endphp

<div {{
    $attributes->class($emptyClasses)->merge([
        'role' => 'presentation',
        'hidden' => true,
        'data-command-empty' => true,
    ])
}}>
    {{ $slot->isNotEmpty() ? $slot : __('stencil-ui::messages.command_empty') }}
</div>

@props([
    'heading' => null,
])

@php
    $headingId = filled($heading)
        ? 'command-group-'.str_replace('.', '', uniqid('', true))
        : null;
@endphp

<div {{
    $attributes->class([
        'command__group',
        'overflow-hidden p-1 text-zinc-950 dark:text-zinc-50',
    ])->merge([
        'role' => 'group',
        'data-command-group' => true,
        'aria-labelledby' => $headingId,
    ])
}}>
    @if (filled($heading))
        <div
            id="{{ $headingId }}"
            class="command__group-heading px-2 py-1.5 text-xs font-medium text-zinc-500 dark:text-zinc-400"
            data-command-group-heading
            role="presentation"
        >
            {{ $heading }}
        </div>
    @endif
    {{ $slot }}
</div>

@props([
    'commandId' => null,
    'listboxId' => null,
    'empty' => null,
    'placeholder' => null,
    'shortcut' => true,
])

@php
    $commandId = filled($commandId)
        ? $commandId
        : 'command-'.str_replace('.', '', uniqid('', true));
    $listboxId = filled($listboxId) ? $listboxId : $commandId.'-listbox';

    $emptyMessage = filled($empty)
        ? (string) $empty
        : __('stencil-ui::messages.command_empty');

    $rootAttributes = $attributes
        ->except('shortcut')
        ->class([
            'command',
            'flex w-full flex-col overflow-hidden rounded-xl bg-white text-zinc-950',
            'dark:bg-zinc-950 dark:text-zinc-50',
        ])
        ->merge([
            'data-command' => true,
            'data-command-id' => $commandId,
            'data-command-listbox-id' => $listboxId,
        ]);
@endphp

<div {{ $rootAttributes }}>
    @if ($shortcut)
        <x-ui::command.input :placeholder="$placeholder" />
        <x-ui::command.list>
            <x-ui::command.empty>{{ $emptyMessage }}</x-ui::command.empty>
            {{ $slot }}
        </x-ui::command.list>
    @else
        {{ $slot }}
    @endif
</div>

@aware([
    'commandId' => null,
    'listboxId' => null,
])

@props([
    'placeholder' => null,
    'commandId' => null,
    'listboxId' => null,
])

@php
    $resolvedPlaceholder = filled($placeholder)
        ? (string) $placeholder
        : __('stencil-ui::messages.command_placeholder');

    $resolvedCommandId = filled($commandId) ? $commandId : null;
    $resolvedListboxId = filled($listboxId)
        ? $listboxId
        : (filled($resolvedCommandId) ? $resolvedCommandId.'-listbox' : null);
    $inputId = filled($resolvedCommandId) ? $resolvedCommandId.'-input' : null;

    $inputAttributes = $attributes
        ->except(['placeholder', 'commandId', 'listboxId'])
        ->class([
            'command__input',
            'flex h-11 w-full min-w-0 bg-transparent py-3 text-sm text-zinc-950 outline-none',
            'placeholder:text-zinc-500 disabled:cursor-not-allowed disabled:opacity-50',
            'dark:text-zinc-50 dark:placeholder:text-zinc-400',
        ])
        ->merge([
            'type' => 'text',
            'role' => 'combobox',
            'aria-autocomplete' => 'list',
            'aria-expanded' => 'true',
            'aria-haspopup' => 'listbox',
            'autocomplete' => 'off',
            'autocorrect' => 'off',
            'spellcheck' => 'false',
            'placeholder' => $resolvedPlaceholder,
            'data-command-input' => true,
            'data-dialog-initial-focus' => true,
        ]);

    if (filled($inputId)) {
        $inputAttributes = $inputAttributes->merge(['id' => $inputId]);
    }

    if (filled($resolvedListboxId)) {
        $inputAttributes = $inputAttributes->merge(['aria-controls' => $resolvedListboxId]);
    }
@endphp

<div
    class="command__input-wrap flex items-center gap-2 border-b border-zinc-200 px-3 dark:border-zinc-800"
    data-command-input-wrap
>
    <x-ui::icon name="search" class="size-4 shrink-0 text-zinc-500 dark:text-zinc-400" data-command-search-icon />
    <input {{ $inputAttributes }} />
</div>

@props([
    'value' => null,
    'disabled' => false,
    'href' => null,
    'kbd' => null,
    'icon' => null,
    'keepOpen' => false,
])

@aware([
    'commandId' => null,
])

@php
    $isDisabled = (bool) $disabled;
    $useLink = filled($href);
    $tag = $useLink ? 'a' : 'button';

    $resolvedCommandId = filled($commandId) ? $commandId : null;
    $optionId = filled($resolvedCommandId) && filled($value)
        ? $resolvedCommandId.'-option-'.preg_replace('/[^a-zA-Z0-9_-]/', '-', (string) $value)
        : null;

    $keywords = filled($value) ? (string) $value : '';

    $itemAttributes = $attributes
        ->except(['value', 'disabled', 'href', 'kbd', 'icon', 'keepOpen'])
        ->class([
            'command__item',
            'relative flex w-full cursor-default items-center gap-2 rounded-md px-2 py-1.5 text-sm outline-none select-none',
            'text-zinc-950 dark:text-zinc-50',
            'hover:bg-zinc-100 data-[highlighted]:bg-zinc-100 dark:hover:bg-zinc-800 dark:data-[highlighted]:bg-zinc-800',
            '[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*=size-])]:size-4',
            '[&_svg:not([class*=text-])]:text-zinc-500 dark:[&_svg:not([class*=text-])]:text-zinc-400',
            $isDisabled ? 'pointer-events-none opacity-50' : null,
        ])
        ->merge([
            'type' => $useLink ? null : 'button',
            'href' => $useLink ? $href : null,
            'role' => 'option',
            'tabindex' => '-1',
            'data-command-item' => true,
            'data-value' => filled($value) ? $value : null,
            'data-keywords' => $keywords !== '' ? $keywords : null,
            'data-keep-open' => $keepOpen ? 'true' : null,
            'data-disabled' => $isDisabled ? 'true' : null,
            'aria-disabled' => $isDisabled ? 'true' : null,
            'aria-selected' => 'false',
            'disabled' => (! $useLink && $isDisabled) ? true : null,
        ]);

    if (filled($optionId)) {
        $itemAttributes = $itemAttributes->merge(['id' => $optionId]);
    }
@endphp

<{{ $tag }} {{ $itemAttributes }}>
    @if (filled($icon))
        <x-ui::icon :name="$icon" class="size-4 shrink-0 text-zinc-500 dark:text-zinc-400" />
    @endif
    <span class="min-w-0 flex-1 truncate text-left" data-command-item-label>{{ $slot }}</span>
    @if (filled($kbd))
        <x-ui::command.shortcut>{{ $kbd }}</x-ui::command.shortcut>
    @endif
</{{ $tag }}>

@aware([
    'commandId' => null,
    'listboxId' => null,
])

@props([
    'listboxId' => null,
])

@php
    $resolvedCommandId = filled($commandId) ? $commandId : null;
    $resolvedListboxId = filled($listboxId)
        ? $listboxId
        : (filled($resolvedCommandId) ? $resolvedCommandId.'-listbox' : null);

    $listAttributes = $attributes
        ->except(['listboxId'])
        ->class([
            'command__list',
            'max-h-[min(300px,50vh)] scroll-py-1 overflow-x-hidden overflow-y-auto p-1',
        ])
        ->merge([
            'role' => 'listbox',
            'tabindex' => '-1',
            'data-command-list' => true,
        ]);

    if (filled($resolvedListboxId)) {
        $listAttributes = $listAttributes->merge(['id' => $resolvedListboxId]);
    }
@endphp

<div {{ $listAttributes }}>{{ $slot }}</div>

/**
 * Stencil — command palette / cmdk (vanilla JS, no Alpine).
 */

const COMMAND_SELECTOR = '[data-command]';
const DIALOG_SHORTCUT_SELECTOR = '[data-command-dialog][data-command-shortcut]';
const initialized = new WeakSet();
const shortcutBound = new WeakSet();

/**
 * @param {ParentNode} root
 */
export function initCommands(root = document) {
    root.querySelectorAll(COMMAND_SELECTOR).forEach((element) => {
        if (!(element instanceof HTMLElement)) {
            return;
        }

        if (initialized.has(element)) {
            return;
        }

        initialized.add(element);
        bindCommand(element);
    });

    bindDocumentShortcuts(root);
}

/**
 * @param {ParentNode} root
 */
function bindDocumentShortcuts(root) {
    const scope = root instanceof Document ? root : document;

    scope.querySelectorAll(DIALOG_SHORTCUT_SELECTOR).forEach((dialog) => {
        if (!(dialog instanceof HTMLDialogElement)) {
            return;
        }

        if (shortcutBound.has(dialog)) {
            return;
        }

        shortcutBound.add(dialog);
        bindDialogShortcut(dialog);
    });
}

/**
 * @param {HTMLDialogElement} dialog
 */
function bindDialogShortcut(dialog) {
    const shortcut = dialog.getAttribute('data-command-shortcut');

    if (!shortcut) {
        return;
    }

    const parsed = parseShortcut(shortcut);

    if (!parsed) {
        return;
    }

    document.addEventListener('keydown', (event) => {
        if (!document.contains(dialog)) {
            return;
        }

        if (!matchesShortcut(event, parsed)) {
            return;
        }

        const target = event.target;

        if (
            target instanceof HTMLElement &&
            (target.isContentEditable ||
                ((target instanceof HTMLInputElement ||
                    target instanceof HTMLTextAreaElement ||
                    target instanceof HTMLSelectElement) &&
                    !dialog.contains(target) &&
                    !event.metaKey &&
                    !event.ctrlKey))
        ) {
            // Allow ⌘K / Ctrl+K from inputs; block bare letter shortcuts while typing.
            if (!parsed.meta && !parsed.ctrl) {
                return;
            }
        }

        event.preventDefault();

        if (dialog.open) {
            dialog.close();

            return;
        }

        openCommandDialog(dialog);
    });
}

/**
 * @param {string} shortcut
 * @returns {{ key: string, meta: boolean, ctrl: boolean, shift: boolean, alt: boolean } | null}
 */
function parseShortcut(shortcut) {
    const parts = shortcut
        .toLowerCase()
        .split('.')
        .map((part) => part.trim())
        .filter(Boolean);

    if (parts.length === 0) {
        return null;
    }

    const key = parts[parts.length - 1];
    const mods = new Set(parts.slice(0, -1));

    return {
        key,
        meta: mods.has('meta') || mods.has('cmd') || mods.has('command'),
        ctrl: mods.has('ctrl') || mods.has('control'),
        shift: mods.has('shift'),
        alt: mods.has('alt') || mods.has('option'),
    };
}

/**
 * @param {KeyboardEvent} event
 * @param {{ key: string, meta: boolean, ctrl: boolean, shift: boolean, alt: boolean }} parsed
 */
function matchesShortcut(event, parsed) {
    const key = event.key.toLowerCase();

    if (key !== parsed.key) {
        return false;
    }

    const metaOrCtrl = parsed.meta || parsed.ctrl;
    const eventMetaOrCtrl = event.metaKey || event.ctrlKey;

    if (metaOrCtrl && !eventMetaOrCtrl) {
        return false;
    }

    if (!metaOrCtrl && (event.metaKey || event.ctrlKey)) {
        return false;
    }

    if (parsed.shift !== event.shiftKey) {
        return false;
    }

    if (parsed.alt !== event.altKey) {
        return false;
    }

    return true;
}

/**
 * @param {HTMLDialogElement} dialog
 */
function openCommandDialog(dialog) {
    if (typeof window !== 'undefined' && window.Stencil?.dialog && dialog.dataset.dialogName) {
        window.Stencil.dialog(dialog.dataset.dialogName).show();

        return;
    }

    if (typeof dialog.showModal === 'function') {
        dialog.showModal();
    } else {
        dialog.setAttribute('open', '');
    }

    const input = dialog.querySelector('[data-command-input]');

    if (input instanceof HTMLInputElement) {
        requestAnimationFrame(() => {
            input.focus();
            input.select();
        });
    }
}

/**
 * @param {HTMLElement} root
 */
function bindCommand(root) {
    const input = root.querySelector('[data-command-input]');
    const list = root.querySelector('[data-command-list]');
    const emptyEl = root.querySelector('[data-command-empty]');

    if (!(input instanceof HTMLInputElement) || !(list instanceof HTMLElement)) {
        return;
    }

    let activeIndex = -1;

    const items = () =>
        Array.from(list.querySelectorAll('[data-command-item]')).filter(
            (node) => node instanceof HTMLElement,
        );

    const visibleEnabledItems = () =>
        items().filter((el) => !el.hidden && !el.hasAttribute('data-disabled'));

    /**
     * @param {HTMLElement} el
     */
    function itemLabel(el) {
        const label = el.querySelector('[data-command-item-label]');

        if (label instanceof HTMLElement) {
            return label.textContent?.trim() ?? '';
        }

        return el.textContent?.trim() ?? '';
    }

    /**
     * @param {HTMLElement} el
     */
    function itemSearchText(el) {
        const keywords = el.getAttribute('data-keywords') ?? '';
        const label = itemLabel(el);

        return `${label} ${keywords}`.trim().toLowerCase();
    }

    /**
     * @param {string} query
     */
    function applyFilter(query) {
        const q = query.trim().toLowerCase();
        let visibleCount = 0;

        items().forEach((el) => {
            const match = q === '' || itemSearchText(el).includes(q);
            el.hidden = !match;

            if (match) {
                visibleCount += 1;
            }
        });

        list.querySelectorAll('[data-command-group]').forEach((group) => {
            if (!(group instanceof HTMLElement)) {
                return;
            }

            const hasVisibleItem = Array.from(group.querySelectorAll('[data-command-item]')).some(
                (item) => item instanceof HTMLElement && !item.hidden,
            );

            group.hidden = !hasVisibleItem;
        });

        list.querySelectorAll('[data-command-separator]').forEach((sep) => {
            if (!(sep instanceof HTMLElement)) {
                return;
            }

            sep.hidden = visibleCount === 0;
        });

        if (emptyEl instanceof HTMLElement) {
            emptyEl.hidden = visibleCount > 0;
        }
    }

    function clearHighlights() {
        items().forEach((el) => {
            el.removeAttribute('data-highlighted');
            el.setAttribute('aria-selected', 'false');
        });
        input.removeAttribute('aria-activedescendant');
    }

    function highlightActive() {
        clearHighlights();
        const enabled = visibleEnabledItems();
        const el = enabled[activeIndex];

        if (!el) {
            return;
        }

        el.setAttribute('data-highlighted', 'true');
        el.setAttribute('aria-selected', 'true');
        el.scrollIntoView({ block: 'nearest' });

        if (el.id) {
            input.setAttribute('aria-activedescendant', el.id);
        }
    }

    /**
     * @param {HTMLElement} el
     * @param {{ fromKeyboard?: boolean }} [options]
     */
    function selectItem(el, options = {}) {
        if (el.hasAttribute('data-disabled')) {
            return;
        }

        const value = el.getAttribute('data-value') ?? '';

        root.dispatchEvent(
            new CustomEvent('stencil:command:select', {
                bubbles: true,
                detail: { value, label: itemLabel(el), element: el },
            }),
        );

        // Keyboard selection synthesizes a click so onclick / Livewire handlers run.
        if (options.fromKeyboard) {
            el.dataset.commandSelectDispatching = 'true';

            if (el instanceof HTMLButtonElement || el instanceof HTMLAnchorElement) {
                el.click();
            }

            delete el.dataset.commandSelectDispatching;
        }

        const keepOpen = el.getAttribute('data-keep-open') === 'true';

        if (!keepOpen) {
            closeNearestDialog(root);
        }
    }

    /**
     * @param {HTMLElement} from
     */
    function closeNearestDialog(from) {
        const dialog = from.closest('dialog[data-dialog-content], dialog[data-command-dialog]');

        if (dialog instanceof HTMLDialogElement && dialog.open) {
            dialog.close();
        }
    }

    function resetHighlight() {
        const enabled = visibleEnabledItems();
        activeIndex = enabled.length > 0 ? 0 : -1;
        highlightActive();
    }

    input.addEventListener('input', () => {
        applyFilter(input.value);
        resetHighlight();
    });

    list.addEventListener('mousemove', (event) => {
        const item =
            event.target instanceof Element ? event.target.closest('[data-command-item]') : null;

        if (!(item instanceof HTMLElement) || item.hasAttribute('data-disabled') || item.hidden) {
            return;
        }

        const enabled = visibleEnabledItems();
        const index = enabled.indexOf(item);

        if (index >= 0 && index !== activeIndex) {
            activeIndex = index;
            highlightActive();
        }
    });

    list.addEventListener('click', (event) => {
        const item =
            event.target instanceof Element ? event.target.closest('[data-command-item]') : null;

        if (!(item instanceof HTMLElement)) {
            return;
        }

        if (item.dataset.commandSelectDispatching === 'true') {
            return;
        }

        // Allow native navigation for links; still close the palette.
        if (!(item instanceof HTMLAnchorElement)) {
            event.preventDefault();
        }

        selectItem(item);
    });

    input.addEventListener('keydown', (event) => {
        const enabled = visibleEnabledItems();

        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();

                if (enabled.length === 0) {
                    break;
                }

                activeIndex = Math.min(activeIndex + 1, enabled.length - 1);

                if (activeIndex < 0) {
                    activeIndex = 0;
                }

                highlightActive();
                break;
            case 'ArrowUp':
                event.preventDefault();

                if (enabled.length === 0) {
                    break;
                }

                activeIndex = Math.max(activeIndex - 1, 0);
                highlightActive();
                break;
            case 'Home':
                if (enabled.length > 0) {
                    event.preventDefault();
                    activeIndex = 0;
                    highlightActive();
                }

                break;
            case 'End':
                if (enabled.length > 0) {
                    event.preventDefault();
                    activeIndex = enabled.length - 1;
                    highlightActive();
                }

                break;
            case 'Enter':
                if (enabled.length > 0 && activeIndex >= 0) {
                    event.preventDefault();
                    const el = enabled[activeIndex];

                    if (el) {
                        selectItem(el, { fromKeyboard: true });
                    }
                }

                break;
            case 'Escape': {
                const dialog = root.closest(
                    'dialog[data-dialog-content], dialog[data-command-dialog]',
                );

                if (dialog instanceof HTMLDialogElement && dialog.open) {
                    event.preventDefault();
                    dialog.close();
                } else if (input.value !== '') {
                    event.preventDefault();
                    input.value = '';
                    applyFilter('');
                    resetHighlight();
                }

                break;
            }
            default:
                break;
        }
    });

    const dialog = root.closest('dialog[data-dialog-content], dialog[data-command-dialog]');

    if (dialog instanceof HTMLDialogElement) {
        dialog.addEventListener('close', () => {
            input.value = '';
            applyFilter('');
            clearHighlights();
            activeIndex = -1;
        });

        dialog.addEventListener('stencil:dialog:open', () => {
            applyFilter(input.value);
            resetHighlight();
        });
    }

    applyFilter('');
    resetHighlight();
}

if (typeof window !== 'undefined') {
    window.Stencil = window.Stencil ?? {};
    window.Stencil.command = {
        init: initCommands,
    };
}

document.addEventListener('stencil:mount', (event) => {
    if (!(event instanceof CustomEvent)) {
        return;
    }

    const mountRoot = event.detail?.root;

    if (!(mountRoot instanceof HTMLElement)) {
        return;
    }

    initCommands(mountRoot);
});

if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => initCommands());
    } else {
        initCommands();
    }
}
